                rootCommentId: item.inReplyToId,
                threadId: item.threadId || item.discussionId
            }, item.reply || '✅ Addressed.');
            posted++;
        } catch (e) {
            console.warn('Failed to reply to comment #' + item.inReplyToId + ':', e);
        }
