                runInRepoFn('git checkout --theirs -- "' + file + '"', workingDir);
                console.log('✅ Resolved conflict keeping origin/main version:', file);
            }
            runInRepoFn('git add "' + file + '"', workingDir);
        } catch (e) {
            throw new Error('Failed to resolve conflict for ' + file + ': ' + e);
        }
    });
}

