function parseReviewReplies(repliesJson) {
    if (!repliesJson) {
        console.warn('outputs/review_replies.json not found — skipping thread replies');
        return null;
    }
    var data;
    try {
        data = JSON.parse(repliesJson);
    } catch (e) {
        console.warn('Failed to parse review_replies.json:', e);
        return null;
