    return replies.length ? replies : null;
}

function buildThreadReplyTarget(item) {
    return {
        rootCommentId: item.inReplyToId,
        threadId: item.threadId || item.discussionId
    };
}

function replyTextFor(item) {
    return item.reply || '✅ Addressed.';
